const body   = $input.first().json.body || $input.first().json;
const binary = $input.first().binary || {};

const sellerId    = String(body.seller_id   || '667209');
const productId   = String(body.product_id  || '');
const productName = body.product_name       || '';
const description = body.description        || '';
const widgetTitle = body.widget_title       || 'Assistente Voomp';
const widgetColor = body.widget_color       || '#fe8700';

if (!productId) throw new Error('product_id é obrigatório');

// Identidade única do agente — isola conteúdo por produto
const origin   = 'VOOMP-' + productId;
const agentId  = 'VOOMP-' + productId;
const filterId = 'VOOMP-' + productId;

// Chaves dos arquivos binários enviados pelo formulário
const fileKeys = Object.keys(binary);

return [{
  json: {
    sellerId, productId, productName, description,
    widgetTitle, widgetColor,
    origin, agentId, filterId,
    fileKeys,
    totalFiles: fileKeys.length,
    baseUrl: 'https://kroton.platosedu.io/api/service-gen-ia'
  }
}];

// Quando os nós 🔲 forem implementados, este nó
// receberá agentId, historyId via referências.
// Por ora usa os dados preparados no nó 2.
const vars = $('Preparar Dados').first().json;

// historyId e fileIds virão dos nós de integração
const historyId = null; // substituir por: $('Criar Histórico · Cogna IA').first().json.historyId
const fileIds   = [];   // substituir por: array coletado no upload

// System message gerado dinamicamente
const systemMessage = [
  `Você é um assistente especialista no produto "${vars.productName}".`,
  'Está no checkout e seu objetivo é tirar dúvidas do comprador.',
  'Se o comprador tentar sair, pergunte o motivo gentilmente',
  'e apresente as formas de pagamento disponíveis do produto.',
  'Responda em português, de forma clara e objetiva.',
  'Nunca invente informações. Use apenas o conteúdo fornecido.'
].join(' ');

// Objeto completo que vai para o GTM tag
const widgetConfig = {
  agentId:        vars.agentId,
  agentType:      'EMBED_CHAT',
  origin:         vars.origin,
  historyId,
  systemMessage,
  filtersIds:     [vars.filterId],
  documentSearch: true,
  provider:       'AZURE_OPENAI',
  title:          vars.widgetTitle,
  color:          vars.widgetColor
};

return [{
  json: {
    status:       'ready',
    sellerId:     vars.sellerId,
    productId:    vars.productId,
    productName:  vars.productName,
    agentId:      vars.agentId,
    origin:       vars.origin,
    historyId,
    fileIds,
    systemMessage,
    widgetConfig,
    createdAt: new Date().toISOString()
  }
}];
